tools.example:
s = SocketConnect["example.com:80"];
WriteString[s, "GET / HTTP/1.1\r\nHost: example.com\r\n\r\n"];
Pause[1]; ByteArrayToString[SocketReadMessage[s]]
Close[s]

api = CloudDeploy[APIFunction[{"city" -> "City", "days" -> Restricted["Integer", {1, 14}] -> 7},
   AirTemperatureData[#city, {DatePlus[Now, -#days], Now}] &, "JSON"], Permissions -> "Public"];
URLExecute[api, {"city" -> "Paris", "days" -> 3}]

s = MailServerConnect["imap.gmail.com", "me@gmail.com", $pw];
unread = MailSearch[MailFolder[s, "INBOX"], <|"Unread" -> True|>];
MailExecute["SaveAttachments", unread, "C:\\inbox"]

s = StartWebSession["Chrome", Visible -> False];
WebExecute[s, "OpenPage" -> "https://www.wolfram.com"];
links = WebExecute[s, "LocateElements" -> "Tag" -> "a"];
WebExecute[s, "ElementText" -> First[links]]
img = WebExecute[s, "CapturePage"];
DeleteObject[s]

wizard = AskFunction[
  Module[{city, days},
   city = Ask[{"city", "Which city?"} -> "City"];
   days = Ask[{"days", "How many days back?"} -> Restricted["Integer", {1, 30}]];
   AskDisplay[DateListPlot[AirTemperatureData[city, {DatePlus[Now, -days], Now}]]]]];
CloudDeploy[wizard, "weather-wizard", Permissions -> "Public"]

gd = ServiceConnect["GoogleDrive"];
gd["Requests"]
files = gd["FileList", "MaxItems" -> 20];
ServiceDisconnect[gd]

(* Python side: zmq REP socket bound to tcp://*:5555 *)
req = SocketConnect["tcp://127.0.0.1:5555", "ZMQ_REQ"];
SocketWriteMessage[req, ExportString[<|"cmd" -> "sum", "x" -> {1, 2, 3}|>, "JSON"]];
ImportString[ByteArrayToString[SocketReadMessage[req]], "RawJSON"]

s = StartWebSession[];
WebExecute[s, "OpenPage" -> "https://www.wolfram.com"];
links = WebExecute[s, "LocateElements" -> "Tag" -> "a"];
hrefs = WebExecute[s, "ElementAttribute" -> {#, "href"}] & /@ Take[links, 5];
DeleteObject[s]
